.wssconces__tocke{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}.wssconces__tocke li{display:flex;gap:14px;align-items:flex-start;list-style:none}
.wssconces__st{flex:0 0 40px;height:40px;border-radius:50%;background:#8c6d32;color:#fff;font-weight:800;display:flex;align-items:center;justify-content:center;font-size:14px}.wssconces__tocke p{margin:4px 0 0;font-size:15px;line-height:1.6;color:#333}
.wssconces__kv{list-style:none;margin:0 0 6px;padding:0}.wssconces__kv li{position:relative;padding-left:30px;margin:0 0 12px;font-size:15.5px;line-height:1.55;list-style:none}
.wssconces__kv li::before{content:"\2713";position:absolute;left:0;top:1px;width:20px;height:20px;border-radius:50%;background:#8c6d32;color:#fff;font-size:12px;display:flex;align-items:center;justify-content:center}
.wssconces__tw{overflow-x:auto}.wssconces__tab{width:100%;border-collapse:collapse;background:#fff;border-radius:14px;overflow:hidden;font-size:15px}
.wssconces__tab th,.wssconces__tab td{padding:12px 14px;border-bottom:1px solid #eee;text-align:center}.wssconces__tab th{background:#8c6d32!important;color:#fff!important;font-weight:700}.wssconces__tab td:first-child,.wssconces__tab th:first-child{text-align:left}
.wssconces__thimg{display:block;width:96px;max-width:100%;height:auto;margin:0 auto 8px;border-radius:10px}.wssconces__th span{display:block}
.wssconces__km--ikona{padding:22px 0 0;text-align:center}.wssconces__km--ikona img{width:72px;height:72px;aspect-ratio:auto;object-fit:contain;margin:0 auto}.wssconces__km--ikona+.wssconces__kt{text-align:center}
.wssconces__da{color:#1f8a4c;font-weight:800}.wssconces__ne{color:#c0392b;font-weight:800}
.wssconces__plavo{background:#8c6d32;color:#fff;text-align:center;font-weight:700;padding:12px 16px;margin:-56px 0 40px;font-size:15px}
.wssconces__pog{margin-top:22px}.wssconces__pog>div{background:#fff;border-radius:14px;box-shadow:0 6px 20px rgba(0,0,0,.07);padding:22px 16px}.wssconces__pog span{color:#444;opacity:1}
.wssconces__sred{display:grid;grid-template-columns:1fr minmax(240px,340px) 1fr;gap:36px;align-items:center;margin-top:18px}.wssconces__sc{display:flex;flex-direction:column;gap:28px}.wssconces__sf strong{display:block;font-size:19px;font-weight:800;margin:0 0 6px}.wssconces__sf strong::after{content:'';display:inline-block;width:9px;height:9px;border-radius:50%;background:#d58a28;margin-left:8px;vertical-align:middle}.wssconces__sf p{margin:0;font-size:15px;line-height:1.6;color:#333}.wssconces__sm img,.wssconces__sm video{width:100%;height:auto;display:block}
.wssconces__karw{position:relative}.wssconces__kar{grid-auto-flow:column;grid-auto-columns:calc((100% - 44px)/3);grid-template-columns:none!important;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.wssconces__kar::-webkit-scrollbar{display:none}.wssconces__kar>*{scroll-snap-align:start}
.wssconces__pus{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;border:0;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.18);font-size:22px;line-height:42px;cursor:pointer;z-index:2;color:#8c6d32;padding:0}.wssconces__pus--l{left:-14px}.wssconces__pus--d{right:-14px}
@media (max-width:860px){.wssconces__kar{grid-auto-columns:82%}.wssconces__pus--l{left:4px}.wssconces__pus--d{right:4px}}
@media (max-width:860px){.wssconces__s{padding:38px 0}.wssconces__dva{grid-template-columns:1fr;gap:22px}.wssconces__dva--rev>div:first-child{order:0}
.wssconces__sred{grid-template-columns:1fr;gap:22px}.wssconces__sm{max-width:300px;margin:0 auto;order:-1}.wssconces__g3,.wssconces__g4,.wssconces__g5{grid-template-columns:1fr 1fr}.wssconces__red4{grid-template-columns:1fr 1fr}.wssconces__plavo{margin-top:-38px}}
@media (max-width:560px){.wssconces__g2,.wssconces__g3,.wssconces__g4{grid-template-columns:1fr}}
.wssconces__polna--ar img,.wssconces__polna--ar video{aspect-ratio:var(--ar);object-fit:cover;height:auto}
@media (max-width:560px){.wssconces__polna--ar img,.wssconces__polna--ar video{aspect-ratio:4/3}}
@media (max-width:560px){.wssconces__tab{font-size:13px}.wssconces__tab th,.wssconces__tab td{padding:10px 6px}.wssconces__tab th:first-child,.wssconces__tab td:first-child{padding-left:10px}}
.wssconces__k{border:0!important;box-shadow:0 8px 24px rgba(140,109,50,.12)}.wssconces__media,.wssconces__polna{border:0!important}
.wssconces__h2 em{color:#8c6d32}.wssconces__kicker{color:#8c6d32}.wssconces__v>.wssconces__zak{text-align:center}
.wssconces__kar .wssconces__k:not(:has(.wssconces__kt)){background:transparent;box-shadow:0 8px 24px rgba(0,0,0,.10)}
.wssconces__karw:has(.wssconces__kt){padding:0 34px}.wssconces__karw:has(.wssconces__kt) .wssconces__pus--l{left:-8px}.wssconces__karw:has(.wssconces__kt) .wssconces__pus--d{right:-8px}
@media (max-width:860px){.wssconces__karw:has(.wssconces__kt){padding:0}.wssconces__karw:has(.wssconces__kt) .wssconces__pus{display:none}}
</style>
<script>
(function(){document.querySelectorAll('.wssconces__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wssconces__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wssconces__pus wssconces__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
